const YouTubeBookmark = ({ videoId, href }) => {
  const [title, setTitle] = useState("Watch on YouTube");
  const [author, setAuthor] = useState("");

  useEffect(() => {
    fetch(`https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v=${videoId}&format=json`)
      .then((r) => r.json())
      .then((data) => {
        if (data.title) setTitle(data.title);
        if (data.author_name) setAuthor(data.author_name);
      })
      .catch(() => {});
  }, [videoId]);

  return (
    <BookmarkCard href={href} target="_blank" rel="noopener noreferrer">
      <BookmarkBody>
        <BookmarkTitle>{title}</BookmarkTitle>
        <BookmarkMeta>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="#ff0000">
            <path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.6A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.6 9.4.6 9.4.6s7.5 0 9.4-.6a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.8 15.5V8.5l6.3 3.5-6.3 3.5z"/>
          </svg>
          {author && <span>{author}</span>}
          {author && <span>·</span>}
          <span>youtube.com</span>
        </BookmarkMeta>
      </BookmarkBody>
      <BookmarkThumb>
        <img src={`https://img.youtube.com/vi/${videoId}/mqdefault.jpg`} alt={title} />
      </BookmarkThumb>
    </BookmarkCard>
  );
};

const NotFound = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 60vh;
  gap: 12px;
  font-size: 20px;
  color: #666666;
`;

const customComponents = {
  img({ src, alt, title }) {
    if (title === "right") {
      return (
        <FloatRight>
          <img src={src} alt={alt} />
          {alt && <span>{alt}</span>}
        </FloatRight>
      );
    }
    return <img src={src} alt={alt} />;
  },
  a({ href, children }) {
    const ytMatch = href?.match(YOUTUBE_REGEX);
    if (ytMatch) {
      return <YouTubeBookmark videoId={ytMatch[1]} href={href} />;
    }
    return (
      <a href={href} target="_blank" rel="noopener noreferrer">
        {children}
      </a>
    );
  },
};

const StoryPage = () => {
  const { slug } = useParams();
  const navigate = useNavigate();
  const story = stories.find((s) => s.slug === slug);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [slug]);

  if (!story) {
    return (
      <Page>
        <TopBar>
          <BackBtn onClick={() => navigate(-1)}>
            <ArrowBackIcon style={{ fontSize: 18 }} /> Back
          </BackBtn>
        </TopBar>
        <NotFound>Story not found.</NotFound>
      </Page>
    );
  }

  const formatDate = (dateStr) =>
    new Date(dateStr).toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });

  const pageUrl = `https://tharoosha.github.io/story/${story.slug}`;

  return (
    <Page>
      <Helmet>
        <title>{story.title} — Tharoosha Vihidun</title>
        <meta name="description" content={story.subtitle} />
        <meta property="og:type" content="article" />
        <meta property="og:url" content={pageUrl} />
        <meta property="og:title" content={story.title} />
        <meta property="og:description" content={story.subtitle} />
        {story.coverImage && <meta property="og:image" content={story.coverImage} />}
        <meta property="og:site_name" content="Tharoosha Vihidun" />
        <meta name="twitter:card" content="summary_large_image" />
        <meta name="twitter:title" content={story.title} />
        <meta name="twitter:description" content={story.subtitle} />
        {story.coverImage && <meta name="twitter:image" content={story.coverImage} />}
      </Helmet>
      <TopBar>
        <BackBtn onClick={() => navigate(-1)}>
          <ArrowBackIcon style={{ fontSize: 18 }} /> Back
        </BackBtn>
      </TopBar>

      {story.coverImage && (
        <CoverImage src={story.coverImage} alt={story.title} $position={story.coverImagePosition} />
      )}

      <ContentArea>
        <CategoryTag>{story.category}</CategoryTag>
        <ArticleTitle>{story.title}</ArticleTitle>
        {story.subtitle && (
          <ArticleSubtitle>{story.subtitle}</ArticleSubtitle>
        )}
        <Meta>
          <span>Vihidun</span>
          <Divider />
          <span>{formatDate(story.date)}</span>
          {story.tags?.length > 0 && (
            <>
              <Divider />
              <span>{story.tags.join(" · ")}</span>
            </>
          )}
        </Meta>

        <MarkdownWrapper>
          <ReactMarkdown components={customComponents}>
            {story.content}
          </ReactMarkdown>
        </MarkdownWrapper>
      </ContentArea>
    </Page>
  );
};

export default StoryPage;
